    const L2 = 3.6 + Math.random() * .9, H1 = .62, H2 = .52 + Math.random() * .1, l2 = 1.62, bicorps = Math.random() < .55;
    box(g, L2, H1, l2, c, 0, .32 + H1 / 2, 0);
