  const BL = 1.45, BW = .76;
  const blond = A.mat({ color: 0xd4a464, roughness: .45 }), rougeB = A.mat({ color: 0xc0262c, roughness: .4 }), noirB = A.mat({ color: 0x151515, roughness: .5 }), inox = A.mat({ color: 0xd5d8db, metalness: .85, roughness: .2 });
