      A.ajoute(new THREE.BoxGeometry(.035, .1, .045), A.mat({ color: joue }), bxk, .955, jz, false);
      A.ajoute(new THREE.SphereGeometry(.022, 8, 6), A.mat({ color: 0xe9c4a0 }), bxk, 1.03, jz, false);
