  A.ajoute(new THREE.BoxGeometry(.1, .14, lpB + .3), cadre, VX - .04, hp + .07, 0, false);
  for (const sg of [-1, 1]) A.ajoute(new THREE.BoxGeometry(.1, hp, .14), cadre, VX - .04, hp / 2, sg * (lpB / 2 + .08), false);   // une simple embrasure, sans porte
