  const noir = new THREE.MeshStandardMaterial({ color: 0x121212, roughness: .7 }), cuir = new THREE.MeshStandardMaterial({ color: 0xb8231c, roughness: .55 }), cuirB = new THREE.MeshStandardMaterial({ color: 0xece4d4, roughness: .6 });
